/**
 * FFI error surface for mobile-linux operations.
 */
public enum MobileLinuxApiErrorFfi {
    case Integrity(detail: String
    )
    case NetworkPolicyUnavailable(detail: String
    )
    case ResourceLimitExceeded(detail: String
    )
    case Io(detail: String
    )
    case Timeout
    case RestartRequired(detail: String
    )
    case LegacySelected
    case Unavailable(detail: String
    )
    case LicenseBlocked(detail: String
    )
    case InvalidRequest(detail: String
    )
    case OperationFailed(detail: String
    )
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeMobileLinuxApiErrorFfi: FfiConverterRustBuffer {
    typealias SwiftType = MobileLinuxApiErrorFfi

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MobileLinuxApiErrorFfi {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return try .Integrity(
                detail: FfiConverterString.read(from: &buf)
            )
        case 2: return try .NetworkPolicyUnavailable(
                detail: FfiConverterString.read(from: &buf)
            )
        case 3: return try .ResourceLimitExceeded(
                detail: FfiConverterString.read(from: &buf)
            )
        case 4: return try .Io(
                detail: FfiConverterString.read(from: &buf)
            )
        case 5: return .Timeout
        case 6: return try .RestartRequired(
                detail: FfiConverterString.read(from: &buf)
            )
        case 7: return .LegacySelected
        case 8: return try .Unavailable(
                detail: FfiConverterString.read(from: &buf)
            )
        case 9: return try .LicenseBlocked(
                detail: FfiConverterString.read(from: &buf)
            )
        case 10: return try .InvalidRequest(
                detail: FfiConverterString.read(from: &buf)
            )
        case 11: return try .OperationFailed(
                detail: FfiConverterString.read(from: &buf)
            )
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MobileLinuxApiErrorFfi, into buf: inout [UInt8]) {
        switch value {
        case let .Integrity(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)

        case let .NetworkPolicyUnavailable(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)

        case let .ResourceLimitExceeded(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)

        case let .Io(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)

        case .Timeout:
            writeInt(&buf, Int32(5))

        case let .RestartRequired(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)

        case .LegacySelected:
            writeInt(&buf, Int32(7))

        case let .Unavailable(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)

        case let .LicenseBlocked(detail):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(detail, into: &buf)

        case let .InvalidRequest(detail):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(detail, into: &buf)

        case let .OperationFailed(detail):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(detail, into: &buf)
        }
    }
}

