    return try FfiConverterTypeRuntimeHandle.lift(rustCallWithError(FfiConverterTypeMobileLinuxApiErrorFfi.lift) {
        uniffi_mobile_linux_runtime_fn_func_create_runtime(
            FfiConverterTypeRuntimeConfig.lower(config), $0
        )
    })
}

